params.command:
$ErrorActionPreference='Stop'
$root=$env:HEAVEN_BRIDGE_REPO
if ([string]::IsNullOrWhiteSpace($root)) { $root=Join-Path $env:USERPROFILE 'HeavenBridgeRepo' }
$root=(Resolve-Path $root).Path
$wt=Join-Path $env:USERPROFILE 'HeavenWorktrees\hcp140-c8b1-exact-20260929-1145'
if (Test-Path $wt) { git -C $root worktree remove --force $wt 2>$null; Remove-Item -Recurse -Force $wt -ErrorAction SilentlyContinue }
git -C $root fetch --quiet origin refs/heads/agent/hcp-phase0-hardening-20260929-1138
if ($LASTEXITCODE -ne 0) { exit $LASTEXITCODE }
git -C $root worktree add --detach $wt c8b1e3479ef2ca556f6b289b4b7cb7e28b70d6c8
if ($LASTEXITCODE -ne 0) { exit $LASTEXITCODE }
$code=0
try {
  Push-Location $wt
  python plugins/heaven-control-plane/verify.py
  if ($LASTEXITCODE -ne 0) { $code=$LASTEXITCODE }
  if ($code -eq 0) { python heaven-bridge/test_worker.py; if ($LASTEXITCODE -ne 0) { $code=$LASTEXITCODE } }
  if ($code -eq 0) { python heaven-bridge/tests/test_worker.py; if ($LASTEXITCODE -ne 0) { $code=$LASTEXITCODE } }
  if ($code -eq 0) { git diff --check; if ($LASTEXITCODE -ne 0) { $code=$LASTEXITCODE } }
} finally {
  Pop-Location -ErrorAction SilentlyContinue
  git -C $root worktree remove --force $wt 2>$null
}
if ($code -ne 0) { exit $code }
Write-Output 'hcp140-c8b1-exact-20260929-1145_OK'
Write-Output 'HEAD=c8b1e3479ef2ca556f6b289b4b7cb7e28b70d6c8'
